// let upgrade = http.Server.bind("0.0.0.0:80");
//
//	spawn { upgrade.serve((req) -> {
//	    baml.http.Response.new(308, { "Location": "https://" + req.headers.get("host") + req.url }, "".to_utf8())
//	}) };
//
